const HOUSE_HI_NAME = [
  'प्रथम (लग्न)', 'द्वितीय (धन)', 'तृतीय (पराक्रम)', 'चतुर्थ (सुख)',
  'पंचम (संतान/विद्या)', 'षष्ठ (रोग/सेवा)', 'सप्तम (विवाह/व्यापार)', 'अष्टम (आयु/गूढ़)',
  'नवम (भाग्य/धर्म)', 'दशम (कर्म/करियर)', 'एकादश (आय/लाभ)', 'द्वादश (व्यय/विदेश)',
];

export function getBhavesha144Entry(
  lordHouse: number,
  placedHouse: number
): Bhavesha144Entry {
  const lh = Math.max(1, Math.min(12, lordHouse));
  const ph = Math.max(1, Math.min(12, placedHouse));
  const row = MATRIX[lh - 1]?.[ph - 1];
  if (!row) {
    return {
      lordHouse: lh,
      placedHouse: ph,
      headlineEn: `Lord of House ${lh} in House ${ph}`,
      headlineHi: `${lh}वें भाव का स्वामी ${ph}वें भाव में`,
      readingEn: `Connects matters of House ${lh} into House ${ph}.`,
      readingHi: `${HOUSE_HI_NAME[lh - 1]} का संबंध ${HOUSE_HI_NAME[ph - 1]} से जुड़ता है।`,
      eventEn: `Major milestones shift during Dasha of this lord.`,
      eventHi: `संबंधित स्वामी की दशा में प्रमुख घटनाएँ घटती हैं।`,
    };
  }
  const [hEn, hHi, rEn, rHi, eEn, eHi] = row;
  return {
    lordHouse: lh,
    placedHouse: ph,
    headlineEn: `${lh}th Lord in ${ph}th House — ${hEn}`,
    headlineHi: `${lh}वें भावेश ${ph}वें भाव में — ${hHi}`,
    readingEn: rEn,
    readingHi: rHi,
    eventEn: eEn,
    eventHi: eHi,
  };
}
